#!/usr/bin/env bash
# Resolves a merge or rebase conflict in a GENERATED file by regenerating it, never by editing it.
#
#   Cargo.lock                                   regenerated by cargo from the (already merged) manifests
#   apps/hq-web/src/strings/en.gen.ts            regenerated by `bun scripts/strings/build.ts`
#   apps/android/.../values/strings_catalogue.xml    (the same command writes both)
#
# Run it in the middle of a conflicted merge or rebase, then `git add` what it lists and continue.
# A generated file that is not in conflict is left alone, unless you pass --all (refresh them anyway).
# The source of the strings, apps/strings/en.yaml, is hand-written: if it is in conflict, resolve it
# first, this script will not guess.
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"

all=0
case "${1:-}" in
    --all) all=1 ;;
    "") ;;
    *) sed -n '2,12p' "$0" | sed 's/^# \{0,1\}//'; exit 2 ;;
esac

CARGO_LOCK=Cargo.lock
WEB_OUT=apps/hq-web/src/strings/en.gen.ts
ANDROID_OUT=apps/android/app/src/main/res/values/strings_catalogue.xml
CATALOGUE=apps/strings/en.yaml

conflicted() { git diff --name-only --diff-filter=U | grep -qxF "$1"; }

# Which side is the target branch? In a merge it is "theirs" (what you are merging in); in a rebase
# it is "ours" (what you are rebasing onto). Either way the generated file is rebuilt from the
# manifests or the catalogue, so this only picks a clean starting point that is not full of markers.
if [ -d "$(git rev-parse --git-path rebase-merge)" ] || [ -d "$(git rev-parse --git-path rebase-apply)" ]; then
    base_side=--ours
else
    base_side=--theirs
fi

done_files=()

if conflicted "$CARGO_LOCK" || [ "$all" = 1 ]; then
    if conflicted "$CARGO_LOCK"; then git checkout "$base_side" -- "$CARGO_LOCK"; fi
    # `cargo metadata` brings the lock in line with every manifest (adds and drops packages, keeps
    # the versions already locked). Offline first; the network only if a new dependency needs it.
    cargo metadata --format-version 1 --offline > /dev/null 2>&1 \
        || cargo metadata --format-version 1 > /dev/null
    done_files+=("$CARGO_LOCK")
fi

if conflicted "$WEB_OUT" || conflicted "$ANDROID_OUT" || [ "$all" = 1 ]; then
    if conflicted "$CATALOGUE"; then
        echo "resolve $CATALOGUE by hand first: it is the source the strings are built from" >&2
        exit 1
    fi
    command -v bun > /dev/null || { echo "bun is needed to regenerate the strings (https://bun.sh)" >&2; exit 1; }
    for f in "$WEB_OUT" "$ANDROID_OUT"; do
        if conflicted "$f"; then git checkout "$base_side" -- "$f"; fi
    done
    bun scripts/strings/build.ts
    done_files+=("$WEB_OUT" "$ANDROID_OUT")
fi

if [ "${#done_files[@]}" = 0 ]; then
    echo "resolve-generated: no generated file is in conflict (use --all to refresh them anyway)"
    exit 0
fi
echo "regenerated: ${done_files[*]}"
echo "now: git add ${done_files[*]}   and continue the merge or rebase"
